<?php
declare(strict_types=1);

final class BackupService
{
    private const TABLES=['user_settings','accounts','categories','transactions','transfers','credit_cards','invoices','card_purchases','invoice_items','invoice_payments','payables','receivables','recurring_transactions','recurrence_occurrences','budgets','budget_alert_levels','goals','goal_contributions','investments','investment_transactions','assets','liabilities','net_worth_snapshots'];
    private const DELETE_ORDER=['goal_contributions','budget_alert_levels','recurrence_occurrences','invoice_payments','invoice_items','investment_transactions','transfers','transactions','payables','receivables','recurring_transactions','assets','liabilities','net_worth_snapshots','goals','budgets','investments','invoices','card_purchases','credit_cards','categories','accounts','user_settings'];
    private const REFERENCES=['transactions'=>['account_id'=>'accounts','category_id'=>'categories'],'transfers'=>['source_account_id'=>'accounts','destination_account_id'=>'accounts'],'credit_cards'=>['payment_account_id'=>'accounts'],'invoices'=>['card_id'=>'credit_cards'],'card_purchases'=>['card_id'=>'credit_cards','category_id'=>'categories'],'invoice_items'=>['invoice_id'=>'invoices','purchase_id'=>'card_purchases'],'invoice_payments'=>['invoice_id'=>'invoices','account_id'=>'accounts'],'payables'=>['account_id'=>'accounts','category_id'=>'categories'],'receivables'=>['account_id'=>'accounts','category_id'=>'categories'],'recurring_transactions'=>['account_id'=>'accounts','category_id'=>'categories'],'recurrence_occurrences'=>['recurring_id'=>'recurring_transactions','transaction_id'=>'transactions'],'budgets'=>['category_id'=>'categories'],'budget_alert_levels'=>['budget_id'=>'budgets'],'goals'=>['account_id'=>'accounts','category_id'=>'categories'],'goal_contributions'=>['goal_id'=>'goals','transfer_id'=>'transfers'],'investment_transactions'=>['investment_id'=>'investments']];

    public static function latestPath(int $userId): string {return dirname(__DIR__,2).'/storage/backups/user-'.$userId.'-latest.json';}
    public static function latestDate(int $userId): ?string {$path=self::latestPath($userId);return is_file($path)?date('d/m/Y H:i',filemtime($path)):null;}
    public static function create(int $userId): string
    {
        $db=Database::connection();$db->beginTransaction();try{$datasets=[];foreach(self::TABLES as $table){$stmt=$db->prepare('SELECT * FROM "'.$table.'" WHERE user_id=:user');$stmt->execute(['user'=>$userId]);$datasets[$table]=$stmt->fetchAll();}$db->commit();}catch(Throwable $error){$db->rollBack();throw $error;}
        $payload=['format_version'=>1,'owner_id'=>$userId,'created_at'=>gmdate('c'),'datasets'=>$datasets];$json=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$payload['checksum']=hash('sha256',$json);$content=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);$directory=dirname(self::latestPath($userId));if(!is_dir($directory))mkdir($directory,0770,true);$tmp=tempnam($directory,'backup-');if($tmp===false)throw new RuntimeException('Não foi possível criar o arquivo de backup.');if(file_put_contents($tmp,$content,LOCK_EX)===false){@unlink($tmp);throw new RuntimeException('Não foi possível gravar o backup.');}@chmod($tmp,0600);if(!rename($tmp,self::latestPath($userId))){@unlink($tmp);throw new RuntimeException('Não foi possível finalizar o backup.');}return self::latestPath($userId);
    }
    public static function restore(string $content,int $userId): void
    {
        if(strlen($content)>25*1024*1024)throw new RuntimeException('O backup excede o limite de 25 MB.');try{$payload=json_decode($content,true,128,JSON_THROW_ON_ERROR);}catch(Throwable){throw new RuntimeException('O arquivo não contém um backup JSON válido.');}
        if(!is_array($payload)||($payload['format_version']??null)!==1||(int)($payload['owner_id']??0)!==$userId||!is_array($payload['datasets']??null)||!is_string($payload['checksum']??null))throw new RuntimeException('O backup não pertence a esta conta ou não é compatível.');$base=['format_version'=>$payload['format_version'],'owner_id'=>$payload['owner_id'],'created_at'=>$payload['created_at']??null,'datasets'=>$payload['datasets']];$expected=hash('sha256',json_encode($base,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));if(!hash_equals($expected,$payload['checksum']))throw new RuntimeException('A integridade do backup não pôde ser confirmada.');
        if(array_diff(self::TABLES,array_keys($payload['datasets']))||array_diff(array_keys($payload['datasets']),self::TABLES))throw new RuntimeException('O conteúdo do backup está incompleto ou contém tabelas não suportadas.');if(count($payload['datasets']['user_settings'])!==1)throw new RuntimeException('O backup não contém as preferências necessárias desta conta.');$count=0;$db=Database::connection();$allowed=[];foreach(self::TABLES as $table){if(!is_array($payload['datasets'][$table]))throw new RuntimeException('A estrutura do backup é inválida.');$count+=count($payload['datasets'][$table]);if($count>100000)throw new RuntimeException('O backup contém dados demais para ser restaurado.');$allowed[$table]=array_column($db->query('PRAGMA table_info("'.$table.'")')->fetchAll(),'name');foreach($payload['datasets'][$table] as $row){if(!is_array($row)||(int)($row['user_id']??0)!==$userId)throw new RuntimeException('Foram encontrados dados de outra conta ou linhas inválidas.');if(array_diff(array_keys($row),$allowed[$table]))throw new RuntimeException('O backup contém campos não suportados. Gere um novo backup no aplicativo atualizado.');}}
        $db->beginTransaction();try{foreach(self::DELETE_ORDER as $table)$db->prepare('DELETE FROM "'.$table.'" WHERE user_id=:user')->execute(['user'=>$userId]);$idMap=[];foreach(self::TABLES as $table){foreach($payload['datasets'][$table] as $row){$oldId=$row['id']??null;unset($row['id']);foreach(self::REFERENCES[$table]??[] as $column=>$parent){if(!array_key_exists($column,$row)||$row[$column]===null)continue;$parentId=(int)$row[$column];if(!isset($idMap[$parent][$parentId]))throw new RuntimeException('O backup referencia um registro ausente.');$row[$column]=$idMap[$parent][$parentId];}$columns=array_keys($row);$quoted=implode(',',array_map(fn($column)=>'"'.$column.'"',$columns));$holders=implode(',',array_map(fn($i)=>':v'.$i,array_keys($columns)));$stmt=$db->prepare('INSERT INTO "'.$table.'" ('.$quoted.') VALUES ('.$holders.')');$values=[];foreach($columns as $i=>$column)$values['v'.$i]=$row[$column];$stmt->execute($values);if($oldId!==null)$idMap[$table][(int)$oldId]=(int)$db->lastInsertId();}}$db->commit();}catch(Throwable $error){$db->rollBack();throw $error;}
    }
}
